# Writes the build information header (commit hash, commit count, whether the working tree has changes).
# Run before every compile (a Visual Studio pre-build step), so the title bar is right even when the project was
# not regenerated by premake. The file is only rewritten when its content changes, to avoid needless recompiles.
param([Parameter(Mandatory = $true)][string]$Out)

$root = Split-Path -Parent $PSScriptRoot
$hash = (git -C $root rev-parse --short HEAD 2>$null)
$count = (git -C $root rev-list --count HEAD 2>$null)
$dirty = [bool](git -C $root status --porcelain 2>$null)
if (-not $hash) { $hash = "unknown" }
if (-not $count) { $count = 0 }

$text = @(
    "// generated by tools/buildinfo.ps1 - do not edit",
    "#pragma once",
    "#define OPENAPE_COMMIT `"$hash`"",
    "#define OPENAPE_COMMIT_COUNT $count",
    "#define OPENAPE_DIRTY $([int]$dirty)",
    ""
) -join "`n"

$old = if (Test-Path $Out) { [IO.File]::ReadAllText($Out) } else { "" }
if ($old -ne $text) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Out) | Out-Null
    [IO.File]::WriteAllText($Out, $text)
}
